import numpy as np
from scipy.optimize import minimize

def objective(x):
    a, b, c = x
    return (a*b - c**2) * (b*c - a**2) * (c*a - b**2)

def constraint(x):
    return x[0]**2 + x[1]**2 + x[2]**2 - 3

cons = {'type': 'eq', 'fun': constraint}

best_min = float('inf')
for _ in range(100):
    start = np.random.uniform(-2, 2, 3)
    res = minimize(objective, start, constraints=cons, method='SLSQP')
    if res.success:
        best_min = min(best_min, res.fun)

print(f"Best min found: {best_min}")

import numpy as np
from scipy.optimize import minimize

def objective(x):
    a, b, c = x
    return (a*b - c**2) * (b*c - a**2) * (c*a - b**2)

def constraint(x):
    return x[0]**2 + x[1]**2 + x[2]**2 - 3

cons = {'type': 'eq', 'fun': constraint}

best_min = float('inf')
for _ in range(1000):
    start = np.random.uniform(-np.sqrt(3), np.sqrt(3), 3)
    res = minimize(objective, start, constraints=cons, method='SLSQP')
    if res.success:
        best_min = min(best_min, res.fun)

print(f"Best min found: {best_min}")
